let particles = [];
let flowField = [];
let cols, rows;
let scl = 20;
let zoff = 0;
let attract = true;

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(5, 5, 15);
  cols = floor(width / scl);
  rows = floor(height / scl);
  flowField = new Array(cols * rows);

  for (let i = 0; i < 3000; i++) {
    particles.push(new Particle());
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  background(5, 5, 15);
  cols = floor(width / scl);
  rows = floor(height / scl);
  flowField = new Array(cols * rows);
}

function draw() {
  // Semi-transparent background for trail effect
  noStroke();
  fill(5, 5, 15, 25);
  rect(0, 0, width, height);

  let yoff = 0;
  for (let y = 0; y < rows; y++) {
    let xoff = 0;
    for (let x = 0; x < cols; x++) {
      let index = x + y * cols;
      let angle = noise(xoff, yoff, zoff) * TWO_PI * 4;
      let v = p5.Vector.fromAngle(angle);
      v.setMag(1);
      flowField[index] = v;
      xoff += 0.1;
    }
    yoff += 0.1;
  }
  zoff += 0.003;

  for (let p of particles) {
    p.follow(flowField);
    p.update();
    p.edges();
    p.show();
  }

  // Overlay text
  fill(255, 255, 255, 180);
  noStroke();
  textSize(16);
  textAlign(LEFT, TOP);
  text('FLOW FIELD \u2022 3,000 particles', 20, 20);
  text('Move mouse to interact \u2022 Click to toggle attract/repel', 20, 42);
  text(attract ? 'MODE: ATTRACT' : 'MODE: REPEL', 20, 64);
}

function mousePressed() {
  attract = !attract;
}

class Particle {
  constructor() {
    this.pos = createVector(random(width), random(height));
    this.vel = createVector(0, 0);
    this.acc = createVector(0, 0);
    this.maxSpeed = 4;
    this.prevPos = this.pos.copy();
    this.hueOffset = random(360);
    this.speedFactor = random(0.5, 1.5);
  }

  follow(vectors) {
    let x = floor(this.pos.x / scl);
    let y = floor(this.pos.y / scl);
    let index = x + y * cols;
    let force = vectors[index];
    if (force) {
      this.applyForce(force);
    }
  }

  applyForce(force) {
    this.acc.add(force);
  }

  update() {
    // Mouse interaction
    let mouse = createVector(mouseX, mouseY);
    let dir = p5.Vector.sub(mouse, this.pos);
    let d = dir.mag();
    if (d < 300) {
      dir.setMag(1);
      if (attract) {
        dir.mult(0.5);
        this.applyForce(dir);
      } else {
        dir.mult(-0.8);
        this.applyForce(dir);
      }
    }

    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed * this.speedFactor);
    this.pos.add(this.vel);
    this.acc.mult(0);
  }

  edges() {
    if (this.pos.x > width) {
      this.pos.x = 0;
      this.updatePrev();
    }
    if (this.pos.x < 0) {
      this.pos.x = width;
      this.updatePrev();
    }
    if (this.pos.y > height) {
      this.pos.y = 0;
      this.updatePrev();
    }
    if (this.pos.y < 0) {
      this.pos.y = height;
      this.updatePrev();
    }
  }

  updatePrev() {
    this.prevPos.x = this.pos.x;
    this.prevPos.y = this.pos.y;
  }

  show() {
    let speed = this.vel.mag();
    let hue = (this.hueOffset + frameCount * 2 + speed * 30) % 360;
    let sat = map(speed, 0, this.maxSpeed, 60, 100);
    let bri = map(speed, 0, this.maxSpeed, 60, 100);
    let alpha = map(speed, 0, this.maxSpeed, 20, 80);

    colorMode(HSB, 360, 100, 100, 100);
    stroke(hue, sat, bri, alpha);
    strokeWeight(map(speed, 0, this.maxSpeed, 0.5, 2));
    line(this.pos.x, this.pos.y, this.prevPos.x, this.prevPos.y);
    colorMode(RGB, 255);

    this.updatePrev();
  }
}

